            font-weight: 300;
            font-style: italic;
            line-height: 1.6;
            color: var(--navy);
            margin-bottom: 2.5rem;
        }

        .testimonial-quote::before {
            content: '"';
            font-size: 5rem;
            color: var(--gold);
            display: block;
            line-height: 0.5;
            margin-bottom: 1rem;
        }

        .testimonial-author {
            font-family: var(--font-accent);
            font-size: 0.75rem;
            letter-spacing: 0.2em;
            text-transform: uppercase;
            color: var(--text-muted);
        }

        .testimonial-dots {
            display: flex;
            gap: 0.8rem;
            justify-content: center;
            margin-top: 3rem;
        }

        .testimonial-dot {
            width: 8px;
            height: 8px;
            border: 1px solid var(--mediterranean);
            border-radius: 50%;
            cursor: none;
            transition: all 0.3s;
            background: none;
        }

        .testimonial-dot.active {
            background: var(--gold);
            border-color: var(--gold);
        }

        /* ============================================
           COLOR THEORY SECTION
           ============================================ */
        .color-theory {
            background: var(--navy);
            color: var(--text-light);
            overflow: hidden;
        }

        .color-theory .section-title {
            color: var(--text-light);
        }

        .color-theory .section-title em {
            color: var(--sky);
        }

        .color-palette-display {
            display: flex;
            gap: 0;
            margin-top: 4rem;
            height: 300px;
            overflow: hidden;
        }

        .color-swatch {
            flex: 1;
            display: flex;
            flex-direction: column;
            justify-content: flex-end;
            padding: 2rem;
            transition: flex 0.8s var(--ease-out-expo);
            cursor: none;
            position: relative;
        }

        .color-swatch:hover {
            flex: 2.5;
        }

        .color-swatch-name {
            font-family: var(--font-accent);
            font-size: 0.6rem;
            letter-spacing: 0.2em;
            text-transform: uppercase;
            opacity: 0.7;
            margin-bottom: 0.3rem;
        }

        .color-swatch-hex {
            font-family: var(--font-display);
            font-size: 1.5rem;
            font-weight: 300;
        }

        .color-theory-text {
            margin-top: 3rem;
            max-width: 700px;
            font-size: 1rem;
            line-height: 1.9;
            color: rgba(244, 241, 235, 0.6);
        }

        /* ============================================
           CONTACT
           ============================================ */
        .contact {
            background: var(--white);
        }

        .contact-grid {
            display: grid;
            grid-template-columns: 1fr 1fr;
            gap: 8rem;
            margin-top: 4rem;
        }

        .contact-info h3 {
            font-family: var(--font-display);
            font-size: 2rem;
            font-weight: 300;
            margin-bottom: 2rem;
            color: var(--navy);
        }

        .contact-info p {
            color: var(--text-muted);
            line-height: 1.8;
            margin-bottom: 2rem;
        }

        .contact-details {
            list-style: none;
            margin-top: 3rem;
        }

        .contact-details li {
            padding: 1.2rem 0;
            border-bottom: 1px solid rgba(11, 29, 58, 0.08);
            display: flex;
            justify-content: space-between;
            align-items: center;
        }

        .contact-details .label {
            font-family: var(--font-accent);
            font-size: 0.65rem;
            letter-spacing: 0.2em;
            text-transform: uppercase;
            color: var(--text-muted);
        }

        .contact-details .value {
            font-size: 0.95rem;
            color: var(--navy);
        }

        .contact-form {
            display: flex;
            flex-direction: column;
            gap: 2rem;
        }

        .form-group {
            position: relative;
        }

        .form-group input,
        .form-group textarea,
        .form-group select {
            width: 100%;
            padding: 1.2rem 0;
            font-family: var(--font-body);
            font-size: 0.95rem;
            font-weight: 300;
            color: var(--navy);
            background: transparent;
            border: none;
            border-bottom: 1px solid rgba(11, 29, 58, 0.15);
            outline: none;
            transition: border-color 0.4s;
            cursor: none;
        }

        .form-group input:focus,
        .form-group textarea:focus,
        .form-group select:focus {
            border-bottom-color: var(--gold);
        }

        .form-group label {
            position: absolute;
            top: 1.2rem;
            left: 0;
            font-family: var(--font-accent);
            font-size: 0.7rem;
            letter-spacing: 0.15em;
            text-transform: uppercase;
            color: var(--text-muted);
            pointer-events: none;
            transition: all 0.3s var(--ease-out-expo);
        }

        .form-group input:focus + label,
        .form-group input:not(:placeholder-shown) + label,
        .form-group textarea:focus + label,
        .form-group textarea:not(:placeholder-shown) + label {
            top: -0.5rem;
            font-size: 0.55rem;
            color: var(--gold-dark);
        }

        .form-group textarea {
            resize: vertical;
            min-height: 120px;
        }

        .form-row {
            display: grid;
            grid-template-columns: 1fr 1fr;
            gap: 2rem;
        }

        .submit-btn {
            font-family: var(--font-accent);
            font-size: 0.75rem;
            letter-spacing: 0.2em;
            text-transform: uppercase;
            color: var(--text-light);
            background: var(--navy);
            border: none;
            padding: 1.5rem 3rem;
            cursor: none;
            position: relative;
            overflow: hidden;
            transition: all 0.5s var(--ease-out-expo);
            align-self: flex-start;
        }

        .submit-btn::before {
            content: '';
            position: absolute;
            inset: 0;
            background: var(--gold);
            transform: translateX(-101%);
            transition: transform 0.5s var(--ease-out-expo);
        }

        .submit-btn:hover::before {
            transform: translateX(0);
        }

        .submit-btn span {
            position: relative;
            z-index: 2;
        }

        .submit-btn:hover {
            color: var(--navy);
        }

        /* ============================================
           FOOTER
           ============================================ */
        .footer {
            background: var(--navy-deep);
            color: var(--text-light);
            padding: 6rem 4rem 3rem;
        }

        .footer-top {
            display: grid;
            grid-template-columns: 2fr 1fr 1fr 1fr;
            gap: 4rem;
            padding-bottom: 4rem;
            border-bottom: 1px solid rgba(255,255,255,0.06);
        }

        .footer-brand {
            font-family: var(--font-display);
            font-size: 2rem;
            font-weight: 300;
            letter-spacing: 0.15em;
            margin-bottom: 1.5rem;
        }

        .footer-brand-desc {
            font-size: 0.9rem;
            color: rgba(244, 241, 235, 0.4);
            line-height: 1.8;
            max-width: 350px;
        }

        .footer-col h4 {
            font-family: var(--font-accent);
            font-size: 0.65rem;
            letter-spacing: 0.25em;
            text-transform: uppercase;
            color: var(--gold);
            margin-bottom: 1.5rem;
        }

        .footer-col ul {
            list-style: none;
        }

        .footer-col li {
            margin-bottom: 0.8rem;
        }

        .footer-col a {
            font-size: 0.85rem;
            color: rgba(244, 241, 235, 0.5);
            transition: color 0.3s;
        }

        .footer-col a:hover {
            color: var(--text-light);
        }

        .footer-bottom {
            display: flex;
            justify-content: space-between;
            align-items: center;
            padding-top: 2.5rem;
            font-size: 0.7rem;
            color: rgba(244, 241, 235, 0.25);
            font-family: var(--font-accent);
            letter-spacing: 0.1em;
        }

        /* ============================================
           RESPONSIVE
           ============================================ */
        @media (max-width: 1024px) {
            .section { padding: 6rem 2.5rem; }
            .about-grid { grid-template-columns: 1fr; gap: 4rem; }
            .services-grid { grid-template-columns: 1fr 1fr; }
            .portfolio-grid {
                grid-template-columns: 1fr 1fr;
                grid-auto-rows: 300px;
            }
            .project-item:nth-child(n) {
                grid-column: auto;
                grid-row: auto;
            }
            .process-timeline { grid-template-columns: 1fr 1fr; gap: 3rem; }
            .process-timeline::before { display: none; }
            .contact-grid { grid-template-columns: 1fr; gap: 4rem; }
            .footer-top { grid-template-columns: 1fr 1fr; }
        }

        @media (max-width: 768px) {
            body { cursor: auto; }
            .cursor-dot, .cursor-ring { display: none; }
            .nav { padding: 1.2rem 1.5rem; }
            .nav-menu { display: none; }
            .nav-toggle { display: flex; }
            .hero { padding: 0 1.5rem 4rem; }
            .section { padding: 5rem 1.5rem; }
            .services-grid { grid-template-columns: 1fr; }
            .portfolio-grid { grid-template-columns: 1fr; grid-auto-rows: 280px; }
            .portfolio-header { flex-direction: column; align-items: flex-start; gap: 2rem; }
            .process-timeline { grid-template-columns: 1fr; }
            .form-row { grid-template-columns: 1fr; }
            .footer-top { grid-template-columns: 1fr; }
            .footer-bottom { flex-direction: column; gap: 1rem; text-align: center; }
            .hero-scroll-indicator { display: none; }
            .color-palette-display { height: 200px; }
        }
    </style>
</head>
