    <!-- PROCESS -->
    <section class="section process" id="proceso">
        <div class="section-tag">04 — Proceso</div>
        <h2 class="section-title">Del <em>diálogo</em> a la materia</h2>
        <div class="process-timeline">
            <div class="process-step">
                <div class="process-dot"></div>
                <div class="process-phase">Fase 01</div>
                <h3 class="process-title">Escucha</h3>
                <p class="process-desc">Entrevistas profundas, análisis del lugar, estudio de la luz natural y mapeo de las rutinas perceptuales del cliente.</p>
            </div>
            <div class="process-step">
                <div class="process-dot"></div>
                <div class="process-phase">Fase 02</div>
                <h3 class="process-title">Concepto</h3>
                <p class="process-desc">Síntesis narrativa del proyecto. Croquis analógicos, maquetas de estudio y definición de la paleta material y cromática.</p>
            </div>
            <div class="process-step">
                <div class="process-dot"></div>
                <div class="process-phase">Fase 03</div>
                <h3 class="process-title">Desarrollo</h3>
                <p class="process-desc">Proyecto ejecutivo BIM, ingeniería de detalle, selección de artesanos y coordinación con la propiedad.</p>
            </div>
            <div class="process-step">
                <div class="process-dot"></div>
                <div class="process-phase">Fase 04</div>
                <h3 class="process-title">Materialización</h3>
                <p class="process-desc">Dirección de obra milimétrica. Control de calidad sensorial: acústica, tacto, temperatura y luz en cada estancia.</p>
            </div>
        </div>
    </section>

