    <script>
        gsap.registerPlugin(ScrollTrigger, ScrollToPlugin, CustomEase);

        // ========================================
        // 1. PRELOADER
        // ========================================
        const preloaderTl = gsap.timeline();
        preloaderTl
            .to('.preloader-logo', { opacity: 1, duration: 0.6, ease: 'power2.out' })
            .to('.preloader-bar-fill', {
                width: '100%',
                duration: 2,
                ease: 'power2.inOut',
                onUpdate: function() {
                    const progress = Math.round(this.progress() * 100);
                    document.querySelector('.preloader-counter').textContent = progress + '%';
                }
            }, '-=0.3')
            .to('.preloader', {
                yPercent: -100,
                duration: 1,
                ease: 'power4.inOut',
                delay: 0.3,
                onComplete: () => {
                    document.querySelector('.preloader').style.display = 'none';
                    initHeroAnimations();
                }
            });

        // ========================================
        // 2. CUSTOM CURSOR
        // ========================================
        const cursorDot = document.querySelector('.cursor-dot');
        const cursorRing = document.querySelector('.cursor-ring');

        if (window.innerWidth > 768) {
            document.addEventListener('mousemove', (e) => {
                gsap.to(cursorDot, { x: e.clientX - 4, y: e.clientY - 4, duration: 0.1 });
                gsap.to(cursorRing, { x: e.clientX - 22, y: e.clientY - 22, duration: 0.25 });
            });

            const hoverTargets = document.querySelectorAll('a, button, .project-item, .service-card, .color-swatch, .filter-btn');
            hoverTargets.forEach(el => {
                el.addEventListener('mouseenter', () => cursorRing.classList.add('hovering'));
                el.addEventListener('mouseleave', () => cursorRing.classList.remove('hovering'));
            });
        }

        // ========================================
        // 3. SCROLL PROGRESS BAR
        // ========================================
        gsap.to('.scroll-progress-bar', {
            width: '100%',
            ease: 'none',
            scrollTrigger: {
                trigger: 'body',
                start: 'top top',
                end: 'bottom bottom',
                scrub: 0.3
            }
        });

        // ========================================
        // 4. NAVIGATION SCROLL EFFECT
        // ========================================
        ScrollTrigger.create({
            start: 100,
            onUpdate: (self) => {
                if (self.direction === 1 && self.scroll() > 100) {
                    document.getElementById('nav').classList.add('scrolled');
                } else if (self.scroll() < 100) {
                    document.getElementById('nav').classList.remove('scrolled');
                }
            }
        });

        // Smooth scroll for nav links
        document.querySelectorAll('.nav-menu a').forEach(link => {
            link.addEventListener('click', (e) => {
                e.preventDefault();
                const target = document.querySelector(link.getAttribute('href'));
                if (target) {
                    gsap.to(window, {
                        duration: 1.5,
                        scrollTo: { y: target, offsetY: 80 },
                        ease: 'power3.inOut'
                    });
                }
            });
        });

        // ========================================
        // 5. HERO ANIMATIONS
        // ========================================
        function initHeroAnimations() {
            const heroTl = gsap.timeline({ defaults: { ease: 'power4.out' }});
            heroTl
                .to('.hero-bg', { scale: 1, duration: 2, ease: 'power2.out' })
                .to('.hero-title .line-inner', {
                    y: 0,
                    duration: 1.4,
                    stagger: 0.12,
                    ease: 'power4.out'
                }, '-=1.5')
                .to('.hero-tag', {
                    opacity: 1,
                    x: 0,
                    duration: 0.8
                }, '-=1')
                .to('.hero-description', {
                    opacity: 1,
                    y: 0,
                    duration: 0.8
                }, '-=0.6');

            // Hero parallax on scroll
            gsap.to('.hero-bg', {
                yPercent: 30,
                scrollTrigger: {
                    trigger: '.hero',
                    start: 'top top',
                    end: 'bottom top',
                    scrub: 1
                }
            });

            gsap.to('.hero-content', {
                yPercent: -20,
                opacity: 0,
                scrollTrigger: {
                    trigger: '.hero',
                    start: '60% top',
                    end: 'bottom top',
                    scrub: 1
                }
            });
        }

        // ========================================
        // 6. ABOUT SECTION
        // ========================================
        gsap.from('.about-image-wrapper', {
            x: -80,
            opacity: 0,
            duration: 1.2,
            ease: 'power3.out',
            scrollTrigger: {
                trigger: '.about',
                start: 'top 70%',
                toggleActions: 'play none none reverse'
            }
        });

        gsap.from('.about-text', {
            x: 80,
            opacity: 0,
            duration: 1.2,
            ease: 'power3.out',
            scrollTrigger: {
                trigger: '.about',
                start: 'top 65%',
                toggleActions: 'play none none reverse'
            }
        });

        // Counter animation
        const counters = document.querySelectorAll('.stat-number');
        counters.forEach(counter => {
            const target = parseInt(counter.dataset.count);
            ScrollTrigger.create({
                trigger: counter,
                start: 'top 85%',
                once: true,
                onEnter: () => {
                    gsap.to(counter, {
                        innerText: target,
                        duration: 2,
                        snap: { innerText: 1 },
                        ease: 'power2.out'
                    });
                }
            });
        });

        // ========================================
        // 7. SERVICES ANIMATION
        // ========================================
        gsap.utils.toArray('.service-card').forEach((card, i) => {
            gsap.from(card, {
                y: 60,
                opacity: 0,
                duration: 0.8,
                delay: i * 0.1,
                ease: 'power3.out',
                scrollTrigger: {
                    trigger: card,
                    start: 'top 85%',
                    toggleActions: 'play none none reverse'
                }
            });
        });

        // ========================================
        // 8. PORTFOLIO ANIMATIONS & FILTERS
        // ========================================
        gsap.utils.toArray('.project-item').forEach((item, i) => {
            gsap.from(item, {
                y: 80,
                opacity: 0,
                scale: 0.95,
                duration: 1,
                delay: i * 0.08,
                ease: 'power3.out',
                scrollTrigger: {
                    trigger: item,
                    start: 'top 90%',
                    toggleActions: 'play none none reverse'
                }
            });
        });

        // Portfolio filter functionality
        const filterBtns = document.querySelectorAll('.filter-btn');
        const projectItems = document.querySelectorAll('.project-item');

        filterBtns.forEach(btn => {
            btn.addEventListener('click', () => {
                filterBtns.forEach(b => b.classList.remove('active'));
                btn.classList.add('active');
                const filter = btn.dataset.filter;

                projectItems.forEach(item => {
                    const category = item.dataset.category;
                    if (filter === 'all' || category === filter) {
                        gsap.to(item, { opacity: 1, scale: 1, duration: 0.5, ease: 'power2.out' });
                        item.style.pointerEvents = 'auto';
                    } else {
                        gsap.to(item, { opacity: 0.15, scale: 0.97, duration: 0.5, ease: 'power2.out' });
                        item.style.pointerEvents = 'none';
                    }
                });
            });
        });

        // ========================================
        // 9. PROCESS TIMELINE
        // ========================================
        gsap.utils.toArray('.process-step').forEach((step, i) => {
            gsap.from(step, {
                y: 50,
                opacity: 0,
                duration: 0.8,
                delay: i * 0.15,
                ease: 'power3.out',
                scrollTrigger: {
                    trigger: '.process-timeline',
                    start: 'top 75%',
                    toggleActions: 'play none none reverse'
                }
            });
        });

        // ========================================
        // 10. COLOR PALETTE ANIMATION
        // ========================================
        gsap.from('.color-swatch', {
            scaleY: 0,
            transformOrigin: 'bottom',
            duration: 1,
            stagger: 0.1,
            ease: 'power3.out',
            scrollTrigger: {
                trigger: '.color-palette-display',
                start: 'top 80%',
                toggleActions: 'play none none reverse'
            }
        });

        // ========================================
        // 11. TESTIMONIAL SLIDER
        // ========================================
        const slides = document.querySelectorAll('.testimonial-slide');
        const dots = document.querySelectorAll('.testimonial-dot');
        let currentSlide = 0;
        let autoSlideInterval;

        function goToSlide(index) {
            slides[currentSlide].classList.remove('active');
            dots[currentSlide].classList.remove('active');
            gsap.to(slides[currentSlide], { opacity: 0, y: 20, duration: 0.4 });

            currentSlide = index;

            slides[currentSlide].classList.add('active');
            dots[currentSlide].classList.add('active');
            gsap.fromTo(slides[currentSlide],
                { opacity: 0, y: -20 },
                { opacity: 1, y: 0, duration: 0.6, ease: 'power2.out' }
            );
        }

        dots.forEach(dot => {
            dot.addEventListener('click', () => {
                clearInterval(autoSlideInterval);
                goToSlide(parseInt(dot.dataset.slide));
                startAutoSlide();
            });
        });

        function startAutoSlide() {
            autoSlideInterval = setInterval(() => {
                goToSlide((currentSlide + 1) % slides.length);
            }, 5000);
        }
        startAutoSlide();

        // ========================================
        // 12. CONTACT FORM
        // ========================================
        document.getElementById('contactForm').addEventListener('submit', (e) => {
            e.preventDefault();
            const btn = e.target.querySelector('.submit-btn span');
            btn.textContent = '¡Mensaje Enviado!';
            gsap.fromTo(btn, { scale: 0.9 }, { scale: 1, duration: 0.4, ease: 'back.out(2)' });
            setTimeout(() => { btn.textContent = 'Enviar Consulta'; }, 3000);
        });

        // ========================================
        // 13. MAGNETIC EFFECT ON CTA BUTTONS
        // ========================================
        if (window.innerWidth > 768) {
            document.querySelectorAll('.nav-cta, .submit-btn').forEach(btn => {
                btn.addEventListener('mousemove', (e) => {
                    const rect = btn.getBoundingClientRect();
                    const x = e.clientX - rect.left - rect.width / 2;
                    const y = e.clientY - rect.top - rect.height / 2;
                    gsap.to(btn, { x: x * 0.2, y: y * 0.2, duration: 0.3, ease: 'power2.out' });
                });
                btn.addEventListener('mouseleave', () => {
                    gsap.to(btn, { x: 0, y: 0, duration: 0.5, ease: 'elastic.out(1, 0.5)' });
                });
            });
        }

        // ========================================
        // 14. REFRESH ON RESIZE
        // ========================================
        let resizeTimer;
        window.addEventListener('resize', () => {
            clearTimeout(resizeTimer);
            resizeTimer = setTimeout(() => ScrollTrigger.refresh(), 250);
        });
    </script>
</body>
</html>
