    <script>
        gsap.registerPlugin(ScrollTrigger, ScrollToPlugin);

        const lenis = new Lenis({ duration: 1.2, easing: t => Math.min(1, 1.001 - Math.pow(2, -10 * t)), smoothWheel: true });
        function raf(time) { lenis.raf(time); requestAnimationFrame(raf); }
        requestAnimationFrame(raf);
        lenis.on('scroll', ScrollTrigger.update);
        gsap.ticker.add(time => lenis.raf(time * 1000));

        const dot = document.querySelector('.cursor-dot');
        const ring = document.querySelector('.cursor-ring');
        let mx = 0, my = 0;
        document.addEventListener('mousemove', e => { mx = e.clientX; my = e.clientY; });
        gsap.ticker.add(() => {
            gsap.set(dot, { x: mx - 4, y: my - 4 });
            gsap.to(ring, { x: mx - 22, y: my - 22, duration: 0.4, ease: 'power2.out' });
        });
        document.querySelectorAll('a, button, .project-card, .service-item').forEach(el => {
            el.addEventListener('mouseenter', () => ring.classList.add('hover'));
            el.addEventListener('mouseleave', () => ring.classList.remove('hover'));
        });

        const counter = { val: 0 };
        const preloaderTl = gsap.timeline();
        preloaderTl
            .to(counter, { val: 100, duration: 2.5, ease: 'power2.inOut', onUpdate: () => document.querySelector('.preloader-counter').textContent = Math.round(counter.val) })
            .to('.preloader-bar-fill', { width: '100%', duration: 2.5, ease: 'power2.inOut' }, 0)
            .to('.preloader', { yPercent: -100, duration: 1, ease: 'power3.inOut', delay: 0.3 })
            .set('.preloader', { display: 'none' })
            .call(() => {
                gsap.to('.hero-bg img', { scale: 1, duration: 2, ease: 'power2.out' });
                gsap.to('.hero-title .line-inner', { y: 0, duration: 1.2, stagger: 0.12, ease: 'power4.out' }, '-=1.5');
                gsap.to('.hero-tag span', { y: 0, duration: 0.8, ease: 'power3.out' }, '-=0.8');
                gsap.to('.hero-subtitle', { opacity: 1, duration: 1, ease: 'power2.out' }, '-=0.5');
            });

        ScrollTrigger.create({ start: 100, onUpdate: self => document.querySelector('.nav').classList.toggle('scrolled', self.scroll() > 100) });

        gsap.utils.toArray('.reveal').forEach(el => {
            gsap.to(el, { opacity: 1, y: 0, duration: 1, ease: 'power3.out', scrollTrigger: { trigger: el, start: 'top 85%' } });
        });

        gsap.utils.toArray('.stat-number').forEach(el => {
            const obj = { val: 0 };
            ScrollTrigger.create({ trigger: el, start: 'top 85%', once: true, onEnter: () => {
                gsap.to(obj, { val: parseInt(el.dataset.count), duration: 2, ease: 'power2.out', onUpdate: () => el.textContent = Math.round(obj.val) });
            }});
        });

        const track = document.querySelector('.portfolio-track');
        const cards = gsap.utils.toArray('.project-card');
        const totalW = cards.reduce((a, c) => a + c.offsetWidth + 48, 0);
        gsap.to(track, {
            x: () => -(totalW - window.innerWidth + 96),
            ease: 'none',
            scrollTrigger: { trigger: '.portfolio-scroll-wrapper', start: 'top top', end: () => `+=${totalW}`, scrub: 1.2, pin: '.portfolio-sticky', anticipatePin: 1, invalidateOnRefresh: true }
        });

        document.querySelectorAll('.magnetic').forEach(btn => {
            btn.addEventListener('mousemove', e => {
                const r = btn.getBoundingClientRect();
                gsap.to(btn, { x: (e.clientX - r.left - r.width/2)*0.3, y: (e.clientY - r.top - r.height/2)*0.3, duration: 0.3, ease: 'power2.out' });
            });
            btn.addEventListener('mouseleave', () => gsap.to(btn, { x: 0, y: 0, duration: 0.5, ease: 'elastic.out(1,0.5)' }));
        });

        document.querySelectorAll('a[href^="#"]').forEach(l => {
            l.addEventListener('click', e => { e.preventDefault(); const t = document.querySelector(l.getAttribute('href')); if(t) lenis.scrollTo(t, { offset: -80, duration: 1.5 }); });
        });

        gsap.to('.hero-bg img', { yPercent: 20, ease: 'none', scrollTrigger: { trigger: '.hero', start: 'top top', end: 'bottom top', scrub: true } });

        window.addEventListener('resize', () => clearTimeout(window._rt) || (window._rt = setTimeout(ScrollTrigger.refresh, 250)));
    </script>
</body>
</html>
