        .stat-number { font-family: var(--font-display); font-size: 2.8rem; font-weight: 300; color: var(--amber-400); line-height: 1; }
        .stat-label { font-size: 0.7rem; letter-spacing: 0.15em; text-transform: uppercase; color: var(--blue-300); margin-top: 0.5rem; }

        /* ROOMS SECTION - New expanded section */
        .rooms { background: var(--blue-900); }
        .rooms-header { max-width: 1200px; margin: 0 auto 6rem; text-align: center; }
        .rooms-header .section-title { max-width: 800px; margin: 0 auto 2rem; }
        .rooms-header p { max-width: 700px; margin: 0 auto; color: var(--blue-300); font-size: 1rem; line-height: 1.8; font-weight: 300; }

        .room-item { max-width: 1400px; margin: 0 auto 10rem; display: grid; grid-template-columns: 1.2fr 1fr; gap: 5rem; align-items: center; }
        .room-item.reverse { grid-template-columns: 1fr 1.2fr; }
        .room-item.reverse .room-visual { order: 2; }
        .room-item.reverse .room-content { order: 1; }

        .room-visual { position: relative; aspect-ratio: 4/3; overflow: hidden; }
        .room-visual img { width: 100%; height: 100%; transition: transform 1.5s var(--ease-out-expo); }
        .room-visual:hover img { transform: scale(1.08); }
        .room-visual::before {
            content: '';
            position: absolute;
            top: -20px;
            left: -20px;
            width: 60%;
            height: 60%;
            border: 1px solid var(--amber-500);
            opacity: 0.4;
            z-index: -1;
            pointer-events: none;
        }
        .room-visual::after {
            content: '';
            position: absolute;
            bottom: -20px;
            right: -20px;
            width: 60%;
            height: 60%;
            border: 1px solid var(--blue-400);
            opacity: 0.3;
            z-index: -1;
            pointer-events: none;
        }

        .room-number { font-family: var(--font-display); font-size: 5rem; font-weight: 300; color: var(--blue-700); line-height: 1; margin-bottom: 1rem; letter-spacing: -0.03em; }
        .room-title { font-family: var(--font-display); font-size: clamp(2rem,3.5vw,3rem); font-weight: 300; color: var(--neutral-50); margin-bottom: 1.5rem; line-height: 1.2; }
        .room-title em { font-style: italic; color: var(--blue-300); }
        .room-description { font-size: 1rem; line-height: 1.9; color: var(--blue-200); font-weight: 300; margin-bottom: 2rem; }

        .room-specs { display: grid; grid-template-columns: 1fr 1fr; gap: 1.5rem; margin-top: 2.5rem; padding-top: 2rem; border-top: 1px solid var(--blue-700); }
        .room-spec-label { font-size: 0.65rem; letter-spacing: 0.3em; text-transform: uppercase; color: var(--amber-500); margin-bottom: 0.3rem; }
        .room-spec-value { font-size: 0.9rem; color: var(--blue-200); font-weight: 300; }

        .room-tags { display: flex; flex-wrap: wrap; gap: 0.6rem; margin-top: 1.5rem; }
        .room-tag { font-size: 0.7rem; letter-spacing: 0.1em; padding: 0.4rem 1rem; border: 1px solid var(--blue-600); color: var(--blue-300); border-radius: 20px; transition: all 0.3s; }
        .room-tag:hover { border-color: var(--amber-500); color: var(--amber-400); }

        /* Portfolio */
        .portfolio { background: var(--blue-800); overflow: hidden; }
        .portfolio-scroll-wrapper { height: 500vh; position: relative; }
        .portfolio-sticky { position: sticky; top: 0; height: 100vh; display: flex; align-items: center; overflow: hidden; }
        .portfolio-track { display: flex; gap: 3rem; padding: 0 3rem; will-change: transform; }
        .project-card { flex-shrink: 0; width: 55vw; max-width: 900px; height: 72vh; position: relative; overflow: hidden; background: var(--blue-700); }
        .project-card-img { width: 100%; height: 100%; transition: transform 1.2s var(--ease-out-expo); }
        .project-card:hover .project-card-img { transform: scale(1.08); }
        .project-card-overlay { position: absolute; inset: 0; background: linear-gradient(0deg, rgba(10,22,40,0.95) 0%, rgba(10,22,40,0.3) 40%, transparent 100%); display: flex; flex-direction: column; justify-content: flex-end; padding: 3rem; }
        .project-card-category { font-size: 0.65rem; letter-spacing: 0.3em; text-transform: uppercase; color: var(--blue-300); margin-bottom: 0.8rem; }
        .project-card-title { font-family: var(--font-display); font-size: 2.2rem; font-weight: 400; color: var(--neutral-50); margin-bottom: 0.5rem; }
        .project-card-location { font-size: 0.85rem; color: var(--blue-200); font-weight: 300; }

        /* Process */
        .process { background: linear-gradient(180deg, var(--blue-900) 0%, var(--blue-800) 100%); }
        .process-grid { display: grid; grid-template-columns: repeat(4,1fr); max-width: 1400px; margin: 4rem auto 0; }
        .process-step { padding: 3rem 2rem; border-right: 1px solid var(--blue-700); position: relative; transition: background 0.5s; }
        .process-step:last-child { border-right: none; }
        .process-step:hover { background: rgba(30,90,138,0.1); }
        .process-step::before { content: ''; position: absolute; top: 0; left: 0; width: 100%; height: 2px; background: var(--amber-500); transform: scaleX(0); transform-origin: left; transition: transform 0.6s var(--ease-out-expo); }
        .process-step:hover::before { transform: scaleX(1); }
        .process-number { font-family: var(--font-display); font-size: 4rem; font-weight: 300; color: var(--blue-700); line-height: 1; margin-bottom: 2rem; transition: color 0.4s; }
        .process-step:hover .process-number { color: var(--blue-500); }
        .process-title { font-family: var(--font-display); font-size: 1.4rem; font-weight: 400; color: var(--neutral-50); margin-bottom: 1rem; }
        .process-desc { font-size: 0.85rem; line-height: 1.7; color: var(--blue-300); font-weight: 300; }

        /* Services */
        .services { background: var(--neutral-50); color: var(--blue-900); }
        .services .section-label { color: var(--amber-600); }
        .services .section-title { color: var(--blue-900); }
        .services .section-title em { color: var(--blue-600); }
        .services-list { max-width: 1200px; margin: 4rem auto 0; }
        .service-item { display: grid; grid-template-columns: auto 1fr auto; align-items: center; gap: 3rem; padding: 2.5rem 0; border-bottom: 1px solid var(--neutral-200); transition: all 0.4s var(--ease-out-expo); }
        .service-item:first-child { border-top: 1px solid var(--neutral-200); }
        .service-item:hover { padding-left: 1.5rem; }
        .service-num { font-family: var(--font-display); font-size: 1rem; color: var(--blue-400); }
        .service-name { font-family: var(--font-display); font-size: 1.8rem; font-weight: 400; color: var(--blue-900); transition: color 0.3s; }
        .service-item:hover .service-name { color: var(--blue-600); }
        .service-arrow { font-size: 1.5rem; color: var(--blue-400); transition: all 0.3s; }
        .service-item:hover .service-arrow { color: var(--amber-600); transform: translateX(10px); }

        /* Testimonial */
        .testimonials { background: var(--blue-800); text-align: center; }
        .testimonial-quote { font-family: var(--font-display); font-size: clamp(1.5rem,3.5vw,2.8rem); font-weight: 300; font-style: italic; line-height: 1.5; max-width: 900px; margin: 0 auto 3rem; color: var(--neutral-100); }
        .testimonial-author { font-size: 0.8rem; letter-spacing: 0.2em; text-transform: uppercase; color: var(--amber-400); }
        .testimonial-role { font-size: 0.75rem; color: var(--blue-300); margin-top: 0.3rem; }

        /* Contact */
        .contact { background: var(--blue-900); }
        .contact-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 6rem; max-width: 1200px; margin: 0 auto; }
        .contact-info p { font-size: 1rem; line-height: 1.9; color: var(--blue-200); font-weight: 300; margin-bottom: 2rem; }
        .contact-detail { margin-bottom: 1.5rem; }
        .contact-detail-label { font-size: 0.65rem; letter-spacing: 0.3em; text-transform: uppercase; color: var(--amber-500); margin-bottom: 0.3rem; }
        .contact-detail-value { font-size: 0.95rem; color: var(--blue-200); line-height: 1.6; }
        .contact-form { display: flex; flex-direction: column; gap: 1.5rem; }
        .form-group { position: relative; }
        .form-group input, .form-group textarea { width: 100%; padding: 1.2rem 0; background: transparent; border: none; border-bottom: 1px solid var(--blue-700); color: var(--neutral-100); font-family: var(--font-body); font-size: 0.9rem; outline: none; transition: border-color 0.3s; }
        .form-group textarea { resize: vertical; min-height: 120px; }
        .form-group input:focus, .form-group textarea:focus { border-color: var(--amber-500); }
        .form-group label { position: absolute; top: 1.2rem; left: 0; font-size: 0.8rem; color: var(--blue-400); pointer-events: none; transition: all 0.3s var(--ease-out-expo); }
        .form-group input:focus ~ label, .form-group input:not(:placeholder-shown) ~ label,
        .form-group textarea:focus ~ label, .form-group textarea:not(:placeholder-shown) ~ label { top: -0.5rem; font-size: 0.6rem; color: var(--amber-500); letter-spacing: 0.1em; text-transform: uppercase; }
        .form-submit { align-self: flex-start; padding: 1rem 3rem; background: var(--amber-500); color: var(--blue-900); font-size: 0.75rem; letter-spacing: 0.2em; text-transform: uppercase; font-weight: 500; transition: all 0.4s var(--ease-out-expo); }
        .form-submit:hover { background: var(--blue-600); color: var(--neutral-50); }

        /* Footer */
        .footer { background: var(--blue-900); border-top: 1px solid var(--blue-800); padding: 4rem 3rem 2rem; }
        .footer-top { display: flex; justify-content: space-between; align-items: flex-start; margin-bottom: 4rem; flex-wrap: wrap; gap: 2rem; }
        .footer-brand { font-family: var(--font-display); font-size: 2rem; font-weight: 300; }
        .footer-social { display: flex; gap: 1.5rem; }
        .footer-social a { font-size: 0.7rem; letter-spacing: 0.15em; text-transform: uppercase; color: var(--blue-300); transition: color 0.3s; }
        .footer-social a:hover { color: var(--amber-500); }
        .footer-bottom { display: flex; justify-content: space-between; padding-top: 2rem; border-top: 1px solid var(--blue-800); font-size: 0.7rem; color: var(--blue-400); opacity: 0.6; flex-wrap: wrap; gap: 1rem; }

        /* Reveal classes */
        .reveal { opacity: 0; transform: translateY(40px); }
        .reveal-left { opacity: 0; transform: translateX(-60px); }
        .reveal-right { opacity: 0; transform: translateX(60px); }
        .reveal-scale { opacity: 0; transform: scale(0.9); }

        /* Magnetic */
        .magnetic { transition: transform 0.3s var(--ease-out-expo); }

        /* Responsive */
        @media (max-width: 1024px) {
            .about-grid, .contact-grid { grid-template-columns: 1fr; gap: 3rem; }
            .process-grid { grid-template-columns: repeat(2,1fr); }
            .process-step { border-right: none; border-bottom: 1px solid var(--blue-700); }
            .project-card { width: 75vw; }
            .room-item, .room-item.reverse { grid-template-columns: 1fr; gap: 3rem; }
            .room-item.reverse .room-visual, .room-item.reverse .room-content { order: initial; }
        }
        @media (max-width: 768px) {
            .nav-menu { display: none; }
            .hero { padding: 0 1.5rem 4rem; }
            .section-padding { padding: 6rem 1.5rem; }
            .process-grid { grid-template-columns: 1fr; }
            .project-card { width: 85vw; height: 60vh; }
            .footer-top { flex-direction: column; }
            body { cursor: auto; }
            .cursor-dot, .cursor-ring { display: none; }
            .hero-scroll { display: none; }
            .room-number { font-size: 3.5rem; }
        }
    </style>
</head>
<body>
    <!-- Preloader -->
    <div class="preloader">
        <div class="preloader-counter">0</div>
        <div class="preloader-bar"><div class="preloader-bar-fill"></div></div>
        <div class="preloader-text">Cargando experiencia</div>
    </div>

    <!-- Cursor -->
    <div class="cursor-dot"></div>
    <div class="cursor-ring"></div>

    <!-- Navigation -->
    <nav class="nav">
        <a href="#" class="nav-logo magnetic">MARC <span>VIDAL</span></a>
        <ul class="nav-menu">
            <li><a href="#about" class="magnetic">Filosofía</a></li>
            <li><a href="#rooms" class="magnetic">Estancias</a></li>
            <li><a href="#portfolio" class="magnetic">Proyectos</a></li>
